const safeHTML=s=>String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function coordinateLabel(lat,lon,d=2){return `${Math.abs(lat).toFixed(d)}° ${lat<0?'S':'N'} · ${Math.abs(lon).toFixed(d)}° ${lon<0?'W':'E'}`}
function selectedShip(){return crafts[state.ship]||crafts.custom}
function timeStamp(dateString,minute=0){return new Date(isoDate(dateString).getTime()+minute*60000)}
// Date-dependent local lunar sky geometry, generated offline from the embedded
// Swiss Ephemeris (Moshier) and IAU 2009 orientation. This is NOT NASA SPICE
// and does not include nearby mountain/crater horizon obstruction.
let ephData=null, ephLoadStatus='LOADING EPHEMERIS';
function unwrapDeg(a,b){let d=((b-a+540)%360)-180;return a+d}
function astroAt(date){if(!ephData)return null;const t=(date.getTime()-Date.parse(ephData.start))/(ephData.stepHours*3600000),i=Math.floor(t);if(i<0||i>=ephData.rows.length-1)return null;const a=ephData.rows[i],b=ephData.rows[i+1],f=t-i;return a.map((v,j)=>v+(j===0||j===2||j===5||j===6?unwrapDeg(v,b[j])-v:b[j]-v)*f)}
function altitudeAt(lat,lon,sublat,sublon){const r=RAD;return Math.asin(clamp(Math.sin(lat*r)*Math.sin(sublat*r)+Math.cos(lat*r)*Math.cos(sublat*r)*Math.cos((lon-sublon)*r),-1,1))*DEG}
function approximatePhase(date){return ((daysSince(date,EPOCH_NEW)/SYNODIC)%1+1)%1}
function getMoonPhase(date){let a=astroAt(date);return a?(((a[5]-a[6])/360)%1+1)%1:approximatePhase(date)}
function angularDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
function sunAltitude(lat,lon,date){let a=astroAt(date);if(a)return altitudeAt(lat,lon,a[1],a[0]);const p=approximatePhase(date);return altitudeAt(lat,lon,1.54*Math.sin(daysSince(date,new Date('2000-01-01T12:00:00Z'))*2*Math.PI/365.256),180-360*p)}
function earthAltitude(lat,lon,date){let a=astroAt(date);if(a)return altitudeAt(lat,lon,a[3],a[2]);const period=daysSince(date,new Date('2000-01-01T12:00:00Z'))/SIDEREAL;return altitudeAt(lat,lon,5.5*Math.cos(2*Math.PI*period),6.5*Math.sin(2*Math.PI*period))}
function lunarOrbitAngle(date){const a=astroAt(date);return (a?a[5]*RAD:2*Math.PI*(daysSince(date,new Date('2000-01-01T12:00:00Z'))/SIDEREAL%1))}
function lunarDistance(date){return astroAt(date)?.[4]||384400}
async function loadEphemeris(){try{let j=window.LUNAR_EPHEMERIS;if(!j){const r=await fetch('lunar_ephemeris_2026_2029.json');if(!r.ok)throw Error('HTTP '+r.status);j=await r.json();}if(j.rows?.length<1000)throw Error('Missing rows');ephData=j;ephLoadStatus='ASTRONOMICAL EPHEMERIS LOADED';}catch(e){ephLoadStatus='FALLBACK ANALYTICAL GEOMETRY';console.warn('Bundled ephemeris not loaded. Serve with a local server.',e)}if($('astroStatus'))$('astroStatus').textContent=ephLoadStatus;if($('modelStatus'))$('modelStatus').textContent=ephLoadStatus;refreshAll();updateSciencePanel();}
const MU=398600.435507, RE=6378.137, RM=384400;
const parkingR=RE+200, sma=(parkingR+RM)/2;
const vCircular=Math.sqrt(MU/parkingR),vTransfer=Math.sqrt(MU*(2/parkingR-1/sma));
const dvTLI=vTransfer-vCircular;
const transferSec=Math.PI*Math.sqrt(sma**3/MU),transferDays=transferSec/86400;
function dvCapability(s){return s.isp*9.80665*Math.log(Math.max(s.dry+s.fuel,1)/Math.max(s.dry,1))/1000}
function fuelForDV(delta,m,isp){return m*(1-Math.exp(-delta*1000/(Math.max(isp,1)*9.80665)))}
function phaseName(p){if(p<.08)return'Translunar injection';if(p<.81)return'Unpowered transfer / coasting';if(p<.88)return'Lunar orbit insertion';if(p<.995)return'Powered lunar descent';return'Touchdown'}
function alignedCost(minute){const date=timeStamp(state.launchDate,minute);const angle=lunarOrbitAngle(date);const l=launchSites[state.launchSite];const earthRotation=2*Math.PI*(minute/1436.07)+l.lon*RAD;const target=state.lon*RAD;return dvTLI+.22*(1-Math.cos(angularDiff(angle+target*.065,earthRotation+Math.PI*.37)))+.06*(1-Math.cos(angle*1.7));}
function bestLaunch(){let m=0,c=Infinity;for(let i=0;i<1440;i+=5){let test=alignedCost(i);if(test<c){m=i;c=test}}let best=m;for(let i=Math.max(0,m-5);i<=Math.min(1439,m+5);i++){let test=alignedCost(i);if(test<c){best=i;c=test}}return best}
function dateMinuteString(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function showPage(num){state.page=num;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',+p.dataset.page===num));document.querySelectorAll('.nav-item').forEach(n=>{let on=+n.dataset.page===num;n.classList.toggle('active',on);n.setAttribute('aria-current',on?'step':'false')});window.scrollTo({top:0,behavior:'smooth'});if(num===1){setTimeout(()=>moonRenderer?.resize(),40)}if(num===5)requestAnimationFrame(renderRoute);refreshPage(num)}
function refreshPage(n){({1:updateLanding,2:updateTrajectory,3:updateEnergy,4:updateComms,5:updateRoute,6:updateComparison})[n]?.()}
function refreshAll(){for(const n of [1,2,3,4,5,6]){if(n!==5)refreshPage(n)}if(state.page===5)renderRoute()}
function setupCommon(){document.querySelectorAll('[data-page]').forEach(b=>{if(b.tagName==='BUTTON')b.addEventListener('click',()=>showPage(+b.dataset.page))});$('themeButton').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);(()=>{try{localStorage.setItem('lunarnav_theme',state.dark?'dark':'light')}catch(e){}})()};try{state.dark=localStorage.getItem('lunarnav_theme')!=='light'}catch(e){state.dark=true};document.body.classList.toggle('dark',state.dark);const modal=$('scienceDialog');$('openSources').onclick=$('aboutButton').onclick=$('showSourcesBottom').onclick=()=>modal.showModal()}
// NASA SVS Moon Kit shares the LRO/LROC data lineage with Moon Trek's basemaps.
// Moon Trek itself is a separate cross-origin application, not a controllable embedded widget.
const NASA_LROC_MAP='https://svs.gsfc.nasa.gov/vis/a000000/a004700/a004720/lroc_color_2k.jpg';
let sharedMoonImage=null, moonMapSource='local fallback texture';
let nasaReferencePhotoLoaded=false;
function refreshMoonPhotoMode(){
 const photo=document.getElementById('nasaMoonPhotoLayer'),cv=document.getElementById('moonCanvas'),guide=document.getElementById('nasaMoonImageGuide');
 if(photo)photo.style.display='none';
 if(cv)cv.classList.remove('photo-reference-only');
 if(guide){
   guide.hidden=moonMapSource==='NASA LROC color mosaic';
   guide.innerHTML='A geographically registered NASA LROC mosaic will show the lunar landmarks directly on the globe. <a href="https://svs.gsfc.nasa.gov/4720/" target="_blank" rel="noopener">NASA LROC imagery ↗</a> · <code>python3 setup_nasa_moon.py</code> caches it for offline use.';
 }
 const foot=document.getElementById('mapSourceQuality');if(foot)foot.textContent=moonMapSource==='NASA LROC color mosaic'?'NASA LROC photographic map active':'LROC map not cached · local texture shown';
}
function loadSharedMoonImage(apply){
 const remotePhoto=document.getElementById('nasaMoonPhoto');if(remotePhoto){
  remotePhoto.addEventListener('load',()=>{nasaReferencePhotoLoaded=true;refreshMoonPhotoMode();},{once:true});
  remotePhoto.addEventListener('error',()=>refreshMoonPhotoMode(),{once:true});
  if(remotePhoto.complete&&remotePhoto.naturalWidth){nasaReferencePhotoLoaded=true;}
 }
 const fallback=new Image();fallback.onload=()=>{if(!sharedMoonImage){sharedMoonImage=fallback;moonMapSource='local fallback texture';apply(fallback);updateMoonSourceStatus();}};fallback.src='moon_texture.jpg';
 const localNASA=new Image();localNASA.onload=()=>{sharedMoonImage=localNASA;moonMapSource='NASA LROC color mosaic';apply(localNASA);updateMoonSourceStatus();};
 localNASA.onerror=()=>{};localNASA.src='moon_texture_nasa.jpg';
 const nasa=new Image();nasa.crossOrigin='anonymous';nasa.onload=()=>{sharedMoonImage=nasa;moonMapSource='NASA LROC color mosaic';apply(nasa);updateMoonSourceStatus();};
 nasa.onerror=()=>updateMoonSourceStatus();nasa.src=NASA_LROC_MAP;
}
function updateMoonSourceStatus(){const label=$('moonSourceBadge');if(label)label.textContent=moonMapSource==='NASA LROC color mosaic'?'NASA LROC PHOTOGRAPHIC MAP':nasaReferencePhotoLoaded?'NASA PHOTO · VIEW ONLY':'NASA DATA DOWNLOAD NEEDED';
 const context=$('regionalSource');if(context)context.textContent=moonMapSource==='NASA LROC color mosaic'?'NASA LRO mosaic · still coarse for landing hazards':'Local conditions · NASA DEM not loaded';
 refreshMoonPhotoMode();}
