 resize(){const rect=this.canvas.getBoundingClientRect();if(!rect.width)return;this.w=Math.round(rect.width);this.h=Math.round(rect.height);const scale=Math.min(2,window.devicePixelRatio||1);this.canvas.width=Math.round(this.w*scale);this.canvas.height=Math.round(this.h*scale);this.overlay.width=this.canvas.width;this.overlay.height=this.canvas.height;this.scale=scale;this.render()}
 rotateBody(p){let cp=Math.cos(this.pitch),sp=Math.sin(this.pitch);let y=cp*p[1]-sp*p[2],z=sp*p[1]+cp*p[2];let cy=Math.cos(this.yaw),sy=Math.sin(this.yaw);return[cy*p[0]+sy*z,y,-sy*p[0]+cy*z]}
