  svg.innerHTML=`<rect x="34" y="9" width="674" height="131" rx="9" fill="#0e1b25"/>${grid}<line x1="34" y1="${sy(skyState.horizon)}" x2="708" y2="${sy(skyState.horizon)}" stroke="#ddd0b2" stroke-dasharray="5 7" opacity=".8"/><path d="${path('sun')}" fill="none" stroke="#e0b772" stroke-width="2.6"/><path d="${path('earth')}" fill="none" stroke="#77b8cc" stroke-width="2.6"/><line x1="${sx(48)}" y1="9" x2="${sx(48)}" y2="140" stroke="#c5dee9" stroke-width="1.5" stroke-dasharray="3 4"/><line id="skyHoverLine" x1="0" x2="0" y1="9" y2="140" stroke="#eee" opacity="0"/><text x="36" y="158" fill="#91a8b7" font-size="10">−48 hours</text><text x="371" y="158" fill="#d2e4ed" font-size="10" text-anchor="middle">Selected time</text><text x="707" y="158" fill="#91a8b7" font-size="10" text-anchor="end">+48 hours</text><text id="skyHoverText" x="700" y="18" text-anchor="end" fill="#e5eced" font-size="10" opacity="0"></text>`;
  svg.onpointermove=e=>{const box=svg.getBoundingClientRect(),x=(e.clientX-box.left)*742/box.width,i=clamp(Math.round((x-34)/674*96),0,96);svg.querySelector('#skyHoverLine')?.setAttribute('x1',sx(i));svg.querySelector('#skyHoverLine')?.setAttribute('x2',sx(i));svg.querySelector('#skyHoverLine')?.setAttribute('opacity','1');const t=svg.querySelector('#skyHoverText');if(t){t.textContent=`${i-48>=0?'+':''}${i-48}h  •  Sun ${fmt(samples[i].sun,1)}°  •  Earth ${fmt(samples[i].earth,1)}°`;t.setAttribute('opacity','1')}};
