// ---------------------------------------------------------------------------
// Module 05 — working A* grid routing (synthetic terrain for demonstration).
// ---------------------------------------------------------------------------
const GW=34,GH=22;
function makeRouteGrid(){const seed=Math.floor(state.lat*13+state.lon*11);let data=[];for(let y=0;y<GH;y++){let row=[];for(let x=0;x<GW;x++){let f=Math.sin(x*.61+y*.28+seed*.003)*.5+Math.cos(y*.66-x*.29+seed*.003)*.35;let nx=Math.sin(x*1.27+y*.97+seed*.01)*.25;let obstruct=f+nx>.62||((x-10)**2+(y-7)**2<14)||((x-23)**2+(y-14)**2<19);let slope=clamp(Math.abs(f)*.7+Math.abs(nx)*.3,0,1);row.push({blocked:obstruct,slope,shade:hash2(x,y,seed)})}data.push(row)}for(let yy=9;yy<=13;yy++)for(let xx=1;xx<=6;xx++)data[yy][xx].blocked=false;data[11][3].blocked=false;data[state.goal.y]?.[state.goal.x]&&(data[state.goal.y][state.goal.x].blocked=false);routeGrid=data}
function pathAStar(){const start={x:3,y:11},goal=state.goal;if(!routeGrid.length)makeRouteGrid();const key=p=>p.y*GW+p.x;const open=[start],came=new Map(),g=new Map([[key(start),0]]),closed=new Set();const h=p=>Math.hypot(p.x-goal.x,p.y-goal.y);let steps=0;while(open.length&&steps++<8000){open.sort((a,b)=>(g.get(key(a))??Infinity)+h(a)-(g.get(key(b))??Infinity)-h(b));let curr=open.shift(),k=key(curr);if(closed.has(k))continue;if(curr.x===goal.x&&curr.y===goal.y){let path=[curr];while(came.has(k)){curr=came.get(k);path.unshift(curr);k=key(curr)}return path}closed.add(k);for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++){if(!xx&&!yy)continue;let x=curr.x+xx,y=curr.y+yy;if(x<0||x>=GW||y<0||y>=GH||routeGrid[y][x].blocked)continue;let v={x,y},vk=key(v),cost=Math.hypot(xx,yy)*(1+routeGrid[y][x].slope*(state.risk===0?.7:state.risk===1?2:5));let tentative=(g.get(k)??Infinity)+cost;if(tentative<(g.get(vk)??Infinity)){g.set(vk,tentative);came.set(vk,curr);open.push(v)}}}return null}
function setupRoute(){const canvas=$('routeCanvas');canvas.addEventListener('click',e=>{let b=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-b.left)/b.width*GW),y=Math.floor((e.clientY-b.top)/b.height*GH);state.goal={x:clamp(x,0,GW-1),y:clamp(y,0,GH-1)};makeRouteGrid();updateRoute()});$('roverEnabled').onchange=e=>{state.rover=e.target.checked;if(state.ship==='custom'){crafts.custom.rover=state.rover}updateRoute()};$('roverSpeed').oninput=e=>{state.roverSpeed=+e.target.value;updateRoute()};$('roverBattery').oninput=e=>{state.roverEnergy=+e.target.value;updateRoute()};$('riskTolerance').oninput=e=>{state.risk=+e.target.value;updateRoute()};$('routeCompute').onclick=()=>updateRoute();makeRouteGrid()}
function drawRouteCanvas(path){let canvas=$('routeCanvas'),ctx=canvas.getContext('2d');let W=canvas.width,H=canvas.height,cw=W/GW,ch=H/GH;ctx.clearRect(0,0,W,H);const grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,'#475767');grad.addColorStop(.6,'#243547');grad.addColorStop(1,'#172638');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){const cell=routeGrid[y][x];let shade=(cell.shade-.5)*17+cell.slope*14;ctx.fillStyle=`rgba(170,187,190,${clamp(.025+shade/220,.015,.17)})`;ctx.fillRect(x*cw,y*ch,cw-1,ch-1);if(cell.blocked){ctx.fillStyle='#b8645860';ctx.fillRect(x*cw,y*ch,cw-1,ch-1)}if((x+y)%7===0){ctx.strokeStyle='#b3d0d51b';ctx.beginPath();ctx.arc((x+.5)*cw,(y+.5)*ch,10+cell.slope*18,0,Math.PI*2);ctx.stroke()}}ctx.strokeStyle='#ffffff11';for(let x=0;x<=GW;x++){ctx.beginPath();ctx.moveTo(x*cw,0);ctx.lineTo(x*cw,H);ctx.stroke()}for(let y=0;y<=GH;y++){ctx.beginPath();ctx.moveTo(0,y*ch);ctx.lineTo(W,y*ch);ctx.stroke()}if(path?.length){ctx.lineWidth=4;ctx.lineJoin='round';ctx.lineCap='round';ctx.strokeStyle='#4bcde4';ctx.shadowColor='#38a7b9';ctx.shadowBlur=10;ctx.beginPath();path.forEach((p,i)=>{let x=(p.x+.5)*cw,y=(p.y+.5)*ch;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.shadowBlur=0;}const pin=(x,y,color,label)=>{ctx.beginPath();ctx.arc((x+.5)*cw,(y+.5)*ch,9,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#fff';ctx.stroke();ctx.font='bold 14px system-ui';ctx.fillStyle='#e5f8ff';ctx.fillText(label,(x+.5)*cw+14,(y+.5)*ch-10)};pin(3,11,'#62c7e0','LANDER');pin(state.goal.x,state.goal.y,'#6dd2b1','SCIENCE TARGET');ctx.font='12px system-ui';ctx.fillStyle='#c1d0db';ctx.fillText('SYNTHETIC TERRAIN — CLICK TO REPOSITION TARGET',15,H-18)}
function updateRoute(){if(!routeGrid.length)makeRouteGrid();$('roverEnabled').checked=state.rover;$('roverSpeed').value=state.roverSpeed;$('roverBattery').value=state.roverEnergy;$('riskTolerance').value=state.risk;$('roverSpeedVal').textContent=fmt(state.roverSpeed,1)+' km/h';$('roverBatteryVal').textContent=fmt(state.roverEnergy,1)+' kWh';$('riskVal').textContent=['Shortest','Balanced','Safest'][state.risk];routeCurrent=state.rover?pathAStar():null;let path=routeCurrent,distance=0;if(path){for(let i=1;i<path.length;i++)distance+=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y)*.020}let energy=distance*.75*(1+state.risk*.13);$('routeDistance').textContent=path?fmt(distance,2)+' km':'—';$('routeDuration').textContent=path?fmt(distance/state.roverSpeed,2)+' h':'—';$('routeEnergy').textContent=path?fmt(energy,2)+' kWh':'—';$('routeHazards').textContent=path?routeGrid.flat().filter(v=>v.blocked).length+' cells':'—';$('routeStatus').textContent=!state.rover?'No rover':!path?'No route':energy>state.roverEnergy?'Energy limited':'Demo route found';renderRoute()}
function renderRoute(){if(!routeGrid.length)makeRouteGrid();drawRouteCanvas(routeCurrent)}
// ---------------------------------------------------------------------------
// Module 06 — visibility opportunity comparisons using simplified geometry.
// ---------------------------------------------------------------------------
function longestTrueRun(flags){let longest=0,run=0;for(let b of flags){run=b?run+1:0;if(run>longest)longest=run;}return longest;}
function computeComparison(){
 const keys=['shackleton','malapert','nobile','blueghost'];
 if(state.selectedSite==='custom')keys[3]='custom';
 const sites=keys.map(key=>key==='custom'?{key,name:'Your selected site',lat:state.lat,lon:state.lon}:{key,...namedSites[key]});
 const start=isoDate(state.compareDate),hours=state.compareDays*24;
 const weight=state.compareObjective==='sun'?[.70,.10,.20]:state.compareObjective==='earth'?[.10,.70,.20]:[.30,.30,.40];
 comparisonResults=sites.map(site=>{
   let sunCount=0,earthCount=0,bothCount=0,series=[],sunFlags=[],earthFlags=[],bothFlags=[];
   const hasDEM=!!(activeDEM && Math.abs(site.lat-activeDEM.lat)<.0002 && Math.abs(site.lon-activeDEM.lon)<.0002 && Array.isArray(activeDEM.horizonDegrees));
   for(let i=0;i<hours;i++){
     const date=new Date(start.getTime()+i*3600000);
     const s=sunAltitude(site.lat,site.lon,date),e=earthAltitude(site.lat,site.lon,date);
     const sh=demHorizon(site.lat,site.lon,date,'sun'),eh=demHorizon(site.lat,site.lon,date,'earth');
     const sunVisible=Number.isFinite(s) && s>(sh??0),earthVisible=Number.isFinite(e)&&e>(eh??0),bothVisible=sunVisible&&earthVisible;
     sunCount+=Number(sunVisible);earthCount+=Number(earthVisible);bothCount+=Number(bothVisible);
     sunFlags.push(sunVisible);earthFlags.push(earthVisible);bothFlags.push(bothVisible);
     series.push({s,e,date,sunVisible,earthVisible,bothVisible});
   }
   const sunPct=100*sunCount/hours,earthPct=100*earthCount/hours,bothPct=100*bothCount/hours;
   return {...site,sunPct,earthPct,bothPct,score:weight[0]*sunPct+weight[1]*earthPct+weight[2]*bothPct,series,
     longestSunHours:longestTrueRun(sunFlags),longestBothHours:longestTrueRun(bothFlags),
     longestDarkHours:longestTrueRun(sunFlags.map(x=>!x)),longestCommBlackoutHours:longestTrueRun(earthFlags.map(x=>!x)),
     hasDEM};
 }).sort((x,y)=>y.score-x.score);
 if(!comparisonResults.some(s=>s.key===state.compareSelected))state.compareSelected=comparisonResults[0].key;
}
function setupComparison(){$('compareDate').onchange=e=>{state.compareDate=e.target.value;updateComparison()};$('compareDays').onchange=e=>{state.compareDays=+e.target.value;updateComparison()};$('compareObjective').onchange=e=>{state.compareObjective=e.target.value;updateComparison()};$('runComparison').onclick=()=>updateComparison();$('chooseBestSite').onclick=()=>{const s=comparisonResults[0];if(!s)return;state.lat=s.lat;state.lon=s.lon;state.selectedSite=s.key;moonRenderer?.center(state.lat,state.lon);refreshAll();showPage(1)};}
function drawComparisonChart(site){const svg=$('comparisonChart');const W=800,H=245,x0=44,y0=18,w=728,h=170;const every=Math.max(1,Math.floor(site.series.length/250));let points=site.series.filter((_,i)=>i%every===0||i===site.series.length-1);const path=key=>points.map((v,i)=>`${i?'L':'M'} ${(x0+i/(points.length-1)*w).toFixed(1)} ${(y0+h-(clamp(v[key],-20,20)+20)/40*h).toFixed(1)}`).join(' ');svg.innerHTML=`${[-20,-10,0,10,20].map(v=>`<line x1="${x0}" y1="${y0+h-(v+20)/40*h}" x2="${x0+w}" y2="${y0+h-(v+20)/40*h}" stroke="#dfe9ed"/><text x="${x0-8}" y="${y0+h-(v+20)/40*h+4}" text-anchor="end" fill="#8da0ab" font-size="10">${v}°</text>`).join('')}<path d="${path('s')}" stroke="#cc9a44" fill="none" stroke-width="2.8"/><path d="${path('e')}" stroke="#269ec4" fill="none" stroke-width="2.8"/><text x="${x0}" y="${H-11}" fill="#94a6b4" font-size="11">${state.compareDate}</text><text x="${x0+w}" y="${H-11}" fill="#94a6b4" font-size="11" text-anchor="end">+${state.compareDays} days</text><line x1="${x0}" y1="${y0+h/2}" x2="${x0+w}" y2="${y0+h/2}" stroke="#9cacb7" stroke-dasharray="5 6"/>`}
function updateComparison(){
 computeComparison();
 $('compareDate').value=state.compareDate;$('compareDays').value=state.compareDays;$('compareObjective').value=state.compareObjective;
 const el=$('comparisonCards');
 el.innerHTML=comparisonResults.map((s,i)=>`<div role="button" tabindex="0" class="comparison-card ${i===0?'best':''} ${state.compareSelected===s.key?'selected':''}" data-key="${s.key}">
  <div class="ranking">${i===0?'✦ HIGHEST OPPORTUNITY SCORE':'SITE 0'+(i+1)}</div>
  <h4 title="${safeHTML(s.name)}">${safeHTML(s.name)}</h4><div class="score">${fmt(s.score,0)}<span>/100</span></div>
  <div class="compare-bar"><i style="width:${s.score}%"></i></div>
  <div class="compare-details"><span>Sun <b>${fmt(s.sunPct,0)}%</b></span><span>Earth <b>${fmt(s.earthPct,0)}%</b></span><span>Both <b>${fmt(s.bothPct,0)}%</b></span></div>
  <div class="science-mini-stats"><span><b>${s.longestDarkHours}h</b> longest darkness</span><span><b>${s.longestCommBlackoutHours}h</b> longest Earth blackout</span><span><b>${s.longestBothHours}h</b> continuous overlap</span></div>
  <div class="science-confidence">${s.hasDEM?'LOLA local skyline imported':'Geometric horizon • terrain not loaded'}</div>
  </div>`).join('');
 el.querySelectorAll('[data-key]').forEach(b=>{b.onclick=()=>{state.compareSelected=b.dataset.key;updateComparison()};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.compareSelected=b.dataset.key;updateComparison()}}});
 const selected=comparisonResults.find(s=>s.key===state.compareSelected)||comparisonResults[0];
 $('visibilityChartTitle').textContent=selected.name;
 const best=comparisonResults[0];$('bestSiteTitle').textContent=best.name;
 $('bestSiteText').textContent=`Over ${state.compareDays} Earth days: Sun above horizon ${fmt(best.sunPct,0)}%, Earth above horizon ${fmt(best.earthPct,0)}%, both simultaneously ${fmt(best.bothPct,0)}%. Longest modeled darkness ${best.longestDarkHours} h; longest direct-Earth outage ${best.longestCommBlackoutHours} h. ${best.hasDEM?'A NASA LOLA local skyline is included where covered.':'Local peaks are not accounted for without a NASA elevation tile.'}`;
 drawComparisonChart(selected);
}
function startApp(){loadTransferAssets();setupCommon();setupSciencePanel();setupLanding();setupTerrainImport();autoLoadNASAHeightPatch();setupTrajectory();setupEnergy();setupComms();setupRoute();setupComparison();syncLandingControls();refreshAll();showPage(1);loadEphemeris();if(!window.WebGLRenderingContext)console.info('WebGL unsupported: basic sphere fallback enabled');console.info('LUNAR/NAV prototype loaded. Results marked demo / approximate where applicable.');}
document.addEventListener('DOMContentLoaded',startApp);
